<script setup>
import { reactive, watch } from 'vue'; import MButton from '../../../components/mds/MButton.vue'; import MInput from '../../../components/mds/MInput.vue'; import MSelect from '../../../components/mds/MSelect.vue';
const props=defineProps({record:Object,editing:Boolean,saving:Boolean,error:String});const emit=defineEmits(['cancel','save']);const draft=reactive({name:'',url:'',type:'news',enabled:true});function reset(record){Object.assign(draft,{name:String(record?.name||''),url:String(record?.url||''),type:['news','social','website','other'].includes(record?.type)?record.type:'news',enabled:record?.enabled!==false});}watch(()=>props.record,reset,{immediate:true,deep:true});const types=[{value:'news',label:'Báo chí'},{value:'social',label:'Mạng xã hội'},{value:'website',label:'Website'},{value:'other',label:'Khác'}];const states=[{value:true,label:'Bật'},{value:false,label:'Tắt'}];function submit(){emit('save',{...draft});}
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><form class="mx-auto max-w-[700px] rounded-lg bg-[var(--mds-bg)] p-5 shadow-[var(--mds-shadow-card)]" @submit.prevent="submit"><header class="mb-5"><h1 class="text-[20px] font-semibold">{{editing?'Sửa nguồn tin':'Thêm nguồn tin'}}</h1><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Máy chủ sẽ kiểm tra URL, mạng nội bộ và RSS trước khi lưu.</p></header><p v-if="error" class="mb-4 rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{error}}</p><div class="grid gap-4 sm:grid-cols-2"><label class="sm:col-span-2"><span class="mb-1 block text-[13px] font-medium">Tên nguồn</span><MInput v-model="draft.name" placeholder="Ví dụ: VnExpress"/></label><label class="sm:col-span-2"><span class="mb-1 block text-[13px] font-medium">URL</span><MInput v-model="draft.url" type="url" placeholder="https://..."/></label><label><span class="mb-1 block text-[13px] font-medium">Loại</span><MSelect v-model="draft.type" :options="types"/></label><label><span class="mb-1 block text-[13px] font-medium">Trạng thái</span><MSelect v-model="draft.enabled" :options="states"/></label></div><footer class="mt-6 flex justify-end gap-2"><MButton variant="neutral" :disabled="saving" @click="emit('cancel')">Hủy</MButton><MButton variant="primary" :loading="saving" @click="submit">{{editing?'Lưu thay đổi':'Thêm nguồn'}}</MButton></footer></form></section></template>
